/*
 * prog29_roman_numeral_parser – reconstructed source
 *
 * The original binary accepted a single command‑line argument that should be a
 * Roman numeral (case‑insensitive).  It validated the numeral, computed its
 * integer value and printed that value.  If the argument was missing, empty,
 * longer than 63 characters, contained illegal characters, represented a value
 * larger than 3999, or was not in the *canonical* Roman form, the program printed
 * the literal string "INVALID".
 *
 * The implementation below follows the same observable behaviour while using a
 * clear, straightforward algorithm.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const char * const SYMS[] = {
    "M",  "CM", "D",  "CD", "C",  "XC",
    "L",  "XL", "X",  "IX", "V",  "IV", "I"
};

static const int VALUES[] = {
    1000, 900, 500, 400, 100, 90,
     50,   40,  10,   9,   5,   4,   1
};

#define SYM_COUNT (sizeof(SYMS)/sizeof(SYMS[0]))
#define MAX_INPUT_LEN 63          /* same limit used by the original binary */
#define MAX_VALUE     3999        /* Roman numerals above 3999 are rejected */

/* Convert a string to an upper‑case copy (output buffer must be large enough). */
static void to_upper(const char *src, char *dst)
{
    while (*src) {
        *dst++ = (char)toupper((unsigned char)*src++);
    }
    *dst = '\0';
}

/* Build the canonical Roman representation of a value (0 <= v <= 3999). */
static void build_canonical(int value, char *out)
{
    size_t pos = 0;
    for (size_t i = 0; i < SYM_COUNT; ++i) {
        while (value >= VALUES[i]) {
            size_t len = strlen(SYMS[i]);
            memcpy(out + pos, SYMS[i], len);
            pos += len;
            value -= VALUES[i];
        }
    }
    out[pos] = '\0';
}

/* Parse the input string (already upper‑cased) and compute its integer value.
 * Returns -1 on any parsing error, otherwise the computed value (0 … 3999). */
static int parse_roman(const char *s)
{
    int total = 0;
    size_t i = 0;
    size_t len = strlen(s);

    while (i < len) {
        int matched = 0;
        for (size_t j = 0; j < SYM_COUNT; ++j) {
            size_t sym_len = strlen(SYMS[j]);
            if (i + sym_len <= len && strncmp(s + i, SYMS[j], sym_len) == 0) {
                total += VALUES[j];
                i += sym_len;
                matched = 1;
                break;
            }
        }
        if (!matched)               /* illegal character or bad ordering */
            return -1;
    }

    if (total == 0 || total > MAX_VALUE)
        return -1;

    return total;
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* The program expects exactly one argument (the Roman numeral). */
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t in_len = strlen(input);

    /* Empty string or overly long input are rejected. */
    if (in_len == 0 || in_len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* Convert to upper case for case‑insensitive handling. */
    char upper[MAX_INPUT_LEN + 1];
    to_upper(input, upper);

    /* Parse the numeral and obtain its integer value. */
    int value = parse_roman(upper);
    if (value == -1) {
        puts("INVALID");
        return 0;
    }

    /* Build the canonical representation of the computed value. */
    char canonical[MAX_INPUT_LEN + 1];
    build_canonical(value, canonical);

    /* The input must match the canonical form exactly. */
    if (strcmp(upper, canonical) != 0) {
        puts("INVALID");
        return 0;
    }

    /* All checks passed – print the integer value. */
    printf("%d\n", value);
    return 0;
}
